      warmUpChannel.setMessageHandler { _, reply in
        Task { @MainActor in
          do {
            try await api.warmUp()
            reply(wrapResult(nil))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      warmUpChannel.setMessageHandler(nil)
    }
  }
}
